/**
 * AskLandingRoute — the /ask (root) placeholder landing surface (story #1273).
 *
 * This surface doubles as the root of the module and the catch-all fallback
 * for any unrecognized sub-path. Later stories (starting with #1274) replace
 * this with the real survey list / builder surfaces.
 */

import { type ReactElement } from "react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { PlaceholderHero } from "../components/PlaceholderHero";

export default function AskLandingRoute(): ReactElement {
  return (
    <PlaceholderHero
      headingId="ask-landing-heading"
      badge={m.ask_landing_badge()}
      heading={m.ask_landing_heading()}
      body={m.ask_landing_body()}
    />
  );
}


