/**
 * AskPlaceholderRoute — the single generic "coming soon" surface rendered
 * behind each Ask sidebar sub-route (Surveys / Analytics / Settings, #1274).
 *
 * Replaces three structurally identical route components (PR #1693 review): the
 * per-route headingId + heading/body message keys come from the ASK_NAV_ROUTES
 * entry, and the paraglide message fns are invoked HERE (inside this
 * component's own render) rather than precomputed by AskApp, so the copy still
 * updates live on a locale switch. Later stories swap this placeholder for the
 * real Surveys / Analytics / Settings surfaces.
 */

import { type ReactElement } from "react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { PlaceholderHero } from "../components/PlaceholderHero";
import { type AskNavRoute } from "./askNavRoutes";

interface AskPlaceholderRouteProps {
  readonly route: AskNavRoute;
}

export default function AskPlaceholderRoute({
  route,
}: AskPlaceholderRouteProps): ReactElement {
  return (
    <PlaceholderHero
      headingId={route.headingId}
      badge={m.ask_landing_badge()}
      heading={route.heading()}
      body={route.body()}
    />
  );
}


--- frontends/ask-mfe/src/routes/SurveyDetailRoute.tsx (396 lines) ---
/**
 * SurveyDetailRoute — /ask/surveys/:id (story #1278, rewritten for #1281 —
 * the survey editor). Renders for EVERY survey, manual or AI-generated
 * (docs/design/ask-ai-survey-generation.md flag 13).
 *
 * Body, keyed on survey.generation_status:
 *   - "generating" -> the simple header (title/type/status, unchanged from
 *     #1278) + AIGeneratingPanel
 *   - "error"       -> the simple header + generation-failed banner
 *     (survey.generation_error, falling back to fixed generic copy)
 *   - "" | "ready"  -> the real editor (story #1281,
 *     docs/design/ask-survey-editor.md): SurveyEditorHeader +
 *     SurveyDetailsCard + SurveyQuestionsCard. Fully interactive for a Draft
 *     survey; read-only (defense-in-depth — SurveyActionsMenu's STATUS_GATE
 *     already disables Edit for Published/Closed, so reaching this route for
 *     a non-draft survey is a theoretical fallback) otherwise.
 *
 * The #1278 "Full editor coming soon" badge is retired in this story — the
 * editor now exists.
 *
 * Survey-level loading uses Skeleton lines/blocks; a failed survey fetch
 * reuses SurveysRetryAlert's existing pattern.
 */

import { useCallback, useRef, useState, type ReactElement, type ReactNode } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { Skeleton } from "@omnicore-platform/ui";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { AIGeneratingPanel } from "../components/AIGeneratingPanel";
import { SurveyStatusBadge } from "../components/SurveyStatusBadge";
import { SurveysRetryAlert } from "../components/SurveysRetryAlert";
import { SurveyEditorHeader } from "../components/editor/SurveyEditorHeader";
import { SurveyDetailsCard } from "../components/editor/SurveyDetailsCard";
import {
  SurveyQuestionsCard,
  sectionLabelledById,
} from "../components/editor/SurveyQuestionsCard";
import { SectionOutlineRail } from "../components/editor/SectionOutlineRail";
import { buildEditorEntries } from "../lib/buildEditorEntries";
import { useQuestionMutations } from "../hooks/useQuestionMutations";
import { useSectionMutations } from "../hooks/useSectionMutations";
import { useSurveyDetail } from "../hooks/useSurveyDetail";
import { useSurveyDetailsForm } from "../hooks/useSurveyDetailsForm";
import { useUnsavedGuard } from "../hooks/useUnsavedGuard";
import { DiscardChangesDialog } from "../components/DiscardChangesDialog";
import type { QuestionDTO } from "../api/questions";
import type { SectionSummary } from "../api/sections";
import type { SurveyDTO, SurveyType } from "../api/surveys";

function surveyTypeLabel(type: SurveyType): string {
  return type === "poll" ? m.ask_surveys_ai_type_poll() : m.ask_surveys_ai_type_survey();
}

/**
 * The simple header shared by the "generating"/"error" generation-status
 * branches — unchanged from #1278 aside from dropping the retired "Full
 * editor coming soon" badge.
 */
function SimpleSurveyHeader({ survey }: { readonly survey: SurveyDTO }): ReactElement {
  return (
    <header className="flex flex-col gap-cog-3 border-b border-cog-divider pb-cog-5">
      <div className="flex flex-wrap items-center justify-between gap-cog-3">
        <h1 className="text-display-lg font-semibold text-cog-text-primary">{survey.title}</h1>
        <SurveyStatusBadge status={survey.status} />
      </div>
      {survey.description && (
        <p className="text-body-md text-cog-text-secondary">{survey.description}</p>
      )}
      <div className="flex flex-wrap items-center gap-cog-2">
        <span className="inline-flex items-center gap-cog-1 rounded-pill border border-cog-divider bg-cog-surface-muted px-cog-2-5 py-cog-1 text-caption font-semibold text-cog-text-secondary">
          {surveyTypeLabel(survey.survey_type)}
        </span>
      </div>
    </header>
  );
}

/**
 * The real editor tree, mounted once both the survey and its questions have
 * loaded. `useQuestionMutations` is created here (not in the parent) so its
 * state is seeded exactly once from `initialQuestions` and persists across
 * this component's own re-renders — `key={survey.id}` on the caller resets
 * it cleanly if the route ever navigates to a different survey id without a
 * full remount.
 */
function SurveyEditorBody({
  survey,
  initialQuestions,
  initialSections,
}: {
  readonly survey: SurveyDTO;
  readonly initialQuestions: readonly QuestionDTO[];
  readonly initialSections: readonly SectionSummary[];
}): ReactElement {
  const mutations = useQuestionMutations(survey.id, initialQuestions);
  const sectionMutations = useSectionMutations(
    survey.id,
    initialSections,
    mutations.questions,
    mutations.moveQuestions,
    mutations.setQuestionsLocally,
  );
  const readOnly = survey.status !== "draft";
  const navigate = useNavigate();
  // Locally-tracked title so the header reflects a rename the moment the
  // details card saves it, without waiting for a full survey refetch.
  const [title, setTitle] = useState(survey.title);
  // `useCallback` so `useSurveyDetailsForm`'s `save` keeps a stable identity —
  // an inline arrow here made it a fresh function on every render, which is
  // what forced that hook to hold draft/baseline refs at all.
  const onDetailsSaved = useCallback((updated: SurveyDTO) => {
    setTitle(updated.title);
  }, []);
  const detailsForm = useSurveyDetailsForm(survey, onDetailsSaved);

  // B2: the details form gets the SAME navigate-away guard every other dirty
  // state in this editor has. Without it, typing a completion message and
  // clicking "Back to Surveys" discarded it silently — while a one-line section
  // title was protected.
  const [detailsLeaveAttempted, setDetailsLeaveAttempted] = useState(false);
  const detailsGuard = useUnsavedGuard({
    isDirty: detailsForm.isDirty,
    onAttemptedLeave: () => setDetailsLeaveAttempted(true),
  });

  // B1: a dirty inline QUESTION editor must gate the Preview navigation too.
  // The questions card publishes its own discard gate here; `useUnsavedGuard`
  // cannot see a button click, so this is the only thing standing between a
  // programmatic navigate and a silently-dropped edit.
  const questionLeaveGate = useRef<((action: () => void) => void) | null>(null);
  const onLeaveGateReady = useCallback((gate: (action: () => void) => void) => {
    questionLeaveGate.current = gate;
  }, []);

  /**
   * Preview auto-saves a DIRTY details card before navigating, so what the
   * preview shows is what respondents would actually get (story #1284's
   * owner-chosen behaviour).
   *
   * Gated on `isDirty` deliberately: a plain Preview click on an unedited
   * survey must issue no PATCH, because a pointless write would still emit an
   * `ask.survey.updated` event and append an audit-chain row from a button
   * labelled "Preview". `useSurveyDetailsForm.save()` also no-ops when the
   * patch is empty, so this is belt-and-braces rather than the only guard.
   *
   * On failure we do NOT navigate: the card renders its own inline error, and
   * silently showing a preview of the OLD stored values after the author's save
   * failed would misrepresent what respondents see.
   */
  async function doPreview(): Promise<void> {
    if (detailsForm.isDirty) {
      const saved = await detailsForm.save();
      if (!saved) return;
    }
    navigate(`/ask/surveys/${survey.id}/preview`);
  }

  function onPreview(): void {
    // Route through the questions card's discard gate first: if an inline
    // question editor holds unsaved changes it opens the SAME dialog an
    // `a[href]` click would, and the preview proceeds only on "Discard
    // changes". Falls straight through when nothing is dirty (or before the
    // card has published its gate, which only happens pre-mount).
    const gate = questionLeaveGate.current;
    if (gate !== null) {
      gate(() => void doPreview());
      return;
    }
    void doPreview();
  }

  return (
    // Block flow, NOT `flex flex-col` — the scroller must be able to overflow.
    // Both card children carry `overflow-hidden` (for their rounded corners), and
    // per CSS Flexbox §4.5 a flex item that clips its overflow has an automatic
    // minimum size of 0. As flex items in a height-constrained column they were
    // therefore squeezed to fit instead of pushing this container past its
    // height: each card clipped its own content, this element never overflowed,
    // no scrollbar appeared, and the editor became reachable only by keyboard
    // (focus scrolls a clipped container programmatically; a wheel does not).
    // Block children cannot shrink at all, so the trap cannot recur here.
    // Spacing comes from the children's own `mb-cog-5`, so this is visually
    // identical to the flex column it replaces.
    // `relative` is load-bearing, not cosmetic. Tailwind's `sr-only` is
    // `position: absolute` with no `top`/`left`, so such an element lays out at
    // its STATIC position but resolves against the nearest positioned ancestor.
    // With none between here and AskLayout's `fixed inset-cog-0` frame, the
    // editor's live regions (`section-live-region`, `drag-live-region`) landed
    // ~990px down in the FRAME's coordinate space and gave it 215px of
    // scrollable overflow it should never have had — invisible, but enough for
    // any programmatic scroll to strand the whole app (#2359). Making this the
    // containing block keeps them inside the scroller, where they are clipped
    // and harmless. See PreviewAnswerControl for the same trap, hit once before.
    <div className="relative min-h-cog-0 flex-1 overflow-y-auto px-cog-5 py-cog-6">
      {/*
        Two columns from `xl` up (redesign board §18, change 2): a 760px
        question column and the sticky section outline beside it. Collapsed
        42px rows stretched across a full-width card were mostly empty space,
        so the width the column gives up carries the outline instead. Below
        `xl` the rail hides itself and this collapses back to one column.
      */}
      <div className="flex w-full items-start gap-cog-5 xl:mx-auto xl:max-w-cog-45">
        <div className="min-w-cog-0 flex-1 xl:max-w-cog-feed">
          <SurveyEditorHeader
            // `title`, not `survey.title` — the locally-tracked copy, so a
            // rename saved from the details card shows without a refetch.
            title={title}
            questionCount={mutations.questions.length}
            status={survey.status}
            onPreview={onPreview}
            previewBusy={detailsForm.isSaving}
          />
          {readOnly ? (
            <SurveyDetailsCard
              readOnly
              title={survey.title}
              description={survey.description}
              completionMessage={survey.completion_message}
            />
          ) : (
            <SurveyDetailsCard form={detailsForm} />
          )}
          <SurveyQuestionsCard
            surveyId={survey.id}
            mutations={mutations}
            sectionMutations={sectionMutations}
            readOnly={readOnly}
            onLeaveGateReady={onLeaveGateReady}
          />
        </div>
        <SectionOutlineRail
          entries={buildEditorEntries(mutations.questions, sectionMutations.sections)}
          sectionHeadingId={sectionLabelledById}
        />
      </div>
      {detailsLeaveAttempted && (
        <DiscardChangesDialog
          // Its default body hardcodes "this question" — the details form needs
          // its own noun, same reason SectionInlineForm passes one.
          body={m.ask_survey_editor_details_discard_body()}
          onKeep={() => {
            setDetailsLeaveAttempted(false);
            detailsGuard.cancelLeave();
          }}
          onDiscard={() => {
            setDetailsLeaveAttempted(false);
            detailsForm.reset();
            detailsGuard.confirmLeave();
          }}
        />
      )}
    </div>
  );
}

/**
 * The one scroll container every state of this route renders into. Six
 * independent early returns each repeated their own copy of these classes, and
 * two of them (the questions loading/error sub-states) had drifted into dropping
 * the survey header entirely — so a slow or failed questions fetch blanked the
 * title the user had just clicked through to. The header now renders ABOVE the
 * state switch whenever the survey itself has loaded.
 *
 * Block flow with `space-y-cog-5`, not a flex column with `gap-cog-5`, for the same
 * reason `SurveyEditorBody` is block flow: none of today's children clip their
 * overflow, so none is currently shrinkable, but one that did would be silently
 * squeezed instead of scrolling. Identical rendering; the hazard simply cannot
 * be reintroduced by a future child.
 */
function DetailPageShell({ children }: { readonly children: ReactNode }): ReactElement {
  // `relative` for the same reason as the editor scroller above: it keeps
  // absolutely positioned descendants (this shell's `sr-only` loading text)
  // resolving against this box rather than escaping to AskLayout's fixed
  // frame and inflating its scrollable overflow (#2359).
  return (
    <div className="relative min-h-cog-0 flex-1 space-y-cog-5 overflow-y-auto px-cog-5 py-cog-6">{children}</div>
  );
}

/** Skeleton lines standing in for the header while the survey itself loads. */
function SurveyHeaderSkeleton(): ReactElement {
  return (
    <div className="flex flex-col gap-cog-3 border-b border-cog-divider pb-cog-5">
      <Skeleton className="h-cog-6 w-cog-19" />
      <Skeleton className="h-cog-4 w-cog-22" />
    </div>
  );
}

function LoadingRegion({ children }: { readonly children: ReactNode }): ReactElement {
  return (
    <div role="status" aria-live="polite" aria-busy="true" className="flex flex-col gap-cog-2">
      <span className="sr-only">{m.ask_surveys_loading()}</span>
      {children}
    </div>
  );
}

export function SurveyDetailRoute(): ReactElement {
  const { id } = useParams<{ id: string }>();
  const detail = useSurveyDetail(id ?? "");

  // Survey-level states: there is no header to show yet.
  if (detail.state === "loading") {
    return (
      <DetailPageShell>
        <LoadingRegion>
          <SurveyHeaderSkeleton />
          <Skeleton className="h-cog-14 w-full" />
        </LoadingRegion>
      </DetailPageShell>
    );
  }

  if (detail.state === "error") {
    return (
      <DetailPageShell>
        <SurveysRetryAlert onRetry={detail.refetch} />
      </DetailPageShell>
    );
  }

  const { survey, questions, sections } = detail;

  // From here on the survey has loaded, so every branch keeps its header.
  if (survey.generation_status === "generating") {
    return (
      <DetailPageShell>
        <SimpleSurveyHeader survey={survey} />
        <AIGeneratingPanel />
      </DetailPageShell>
    );
  }

  if (survey.generation_status === "error") {
    return (
      <DetailPageShell>
        <SimpleSurveyHeader survey={survey} />
        <p
          role="alert"
          className="rounded-lg border border-cog-danger-200 bg-cog-danger-50 px-cog-4 py-cog-3 text-body-sm text-cog-danger-700 dark:border-transparent dark:bg-cog-danger-dark-bg dark:text-cog-danger-dark"
        >
          {survey.generation_error && survey.generation_error !== ""
            ? survey.generation_error
            : m.ask_survey_detail_generation_failed()}
        </p>
      </DetailPageShell>
    );
  }

  // Combined gate (design doc §7 "single combined gate"): one skeleton for
  // the editor body while EITHER questions or sections is still loading,
  // rather than mounting the interactive editor on questions alone and
  // flashing in section bars a moment later once sections resolves
  // separately. The survey header (above) is unaffected either way — it
  // renders the instant the survey itself resolves.
  if (questions.state === "loading" || sections.state === "loading") {
    return (
      <DetailPageShell>
        <SimpleSurveyHeader survey={survey} />
        <LoadingRegion>
          <Skeleton className="h-cog-10 w-full" />
          <Skeleton className="h-cog-10 w-full" />
        </LoadingRegion>
      </DetailPageShell>
    );
  }

  if (questions.state === "error") {
    return (
      <DetailPageShell>
        <SimpleSurveyHeader survey={survey} />
        <SurveysRetryAlert onRetry={questions.refetch} />
      </DetailPageShell>
    );
  }

  if (sections.state === "error") {
    return (
      <DetailPageShell>
        <SimpleSurveyHeader survey={survey} />
        <SurveysRetryAlert onRetry={sections.refetch} />
      </DetailPageShell>
    );
  }

  return (
    <SurveyEditorBody
      key={survey.id}
      survey={survey}
      initialQuestions={questions.questions}
      initialSections={sections.sections}
    />
  );
}


--- frontends/ask-mfe/src/routes/SurveyPreviewRoute.tsx (462 lines) ---
/**
 * SurveyPreviewRoute — `/ask/surveys/:id/preview` (story #1284).
 *
 * The respondent's-eye view of a survey: sections as headings with their
 * descriptions, questions in survey order with genuinely interactive controls,
 * required-answer validation on Submit, and the author's **completion message**
 * on the post-submission screen (falling back to the platform default when the
 * author hasn't set one). This is the surface that makes #1284's journey steps
 * 4-6 real.
 *
 * **Nothing is persisted.** No `ResponseService.Submit`, no POST to the public
 * respondent routes (which are 501 stubs anyway), no `ask.responses` row. A
 * preview that recorded a response would inflate `Survey.response_count` and
 * corrupt the per-survey analytics epic #1291 builds on it. The banner says so
 * plainly rather than leaving the respondent-facing fiction ambiguous.
 *
 * **Why this route exists here at all.** A sweep of every `module: ask` issue
 * found no story that owns survey preview — #1286 publishes and #1287 generates
 * a deployment URL, but neither builds a viewing surface. Rather than ship a
 * completion-message field whose effect an author cannot see, preview lands
 * with the field that needs it. It also retires the *Preview* half of
 * divergence 3 in docs/design/ask-survey-editor.md ("no Preview / Publish
 * Survey / kebab in the editor header"); Publish stays absent for #1286.
 *
 * Ordering comes from `buildEditorEntries`, NOT a second implementation. That
 * algorithm is already duplicated between ask-svc and this MFE and the two are
 * required to agree exactly, including the `(position, id)` section tiebreak —
 * a third copy here would be a third thing to keep in step.
 */

import { useEffect, useRef, type ReactElement } from "react";
import { Link, useParams } from "react-router-dom";
import { ArrowLeft, CheckCircle2, Info } from "@omnicore-platform/ui/icons";
import { Button, Skeleton } from "@omnicore-platform/ui";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { PreviewFlowRunner } from "../components/preview/PreviewFlowRunner";
import { PreviewQuestionCard } from "../components/preview/PreviewQuestionCard";
import { SurveysRetryAlert } from "../components/SurveysRetryAlert";
import { usePreviewAnswers } from "../hooks/usePreviewAnswers";
import { useSurveyDetail } from "../hooks/useSurveyDetail";
import { buildEditorEntries } from "../lib/buildEditorEntries";
import { initialAnswer } from "../lib/previewAnswers";
import { hasAnyBranch } from "../lib/surveyTraversal";
import type { QuestionDTO } from "../api/questions";
import type { SectionSummary } from "../api/sections";
import type { SurveyDTO } from "../api/surveys";

/** The one scroll container every state of this route renders into. */
function PreviewShell({
  children,
  surveyId,
}: {
  readonly children: React.ReactNode;
  readonly surveyId: string;
}): ReactElement {
  return (
    <div className="min-h-cog-0 flex-1 overflow-y-auto px-cog-5 py-cog-6">
      <Link
        to={`/ask/surveys/${surveyId}`}
        className="mb-cog-4 inline-flex w-fit items-center gap-cog-2 rounded-md text-body-md font-medium text-cog-text-secondary transition-colors duration-standard hover:text-cog-text-primary focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus"
      >
        <ArrowLeft aria-hidden="true" className="h-cog-4 w-cog-4 rtl:-scale-x-100" />
        {m.ask_survey_preview_back_cta()}
      </Link>
      {/* max-w keeps the respondent column readable rather than stretching a
          question across a 1440px canvas. */}
      <div className="mx-auto max-w-cog-feed">{children}</div>
    </div>
  );
}

/** The persistent "this is a preview" banner. */
function PreviewNotice(): ReactElement {
  return (
    <p className="mb-cog-5 flex items-start gap-cog-2 rounded-lg border border-cog-blue-100 bg-cog-blue-50 px-cog-4 py-cog-3 text-body-sm text-cog-blue-700 dark:border-transparent dark:bg-cog-blue-950 dark:text-cog-blue-300">
      <Info aria-hidden="true" className="mt-cog-0-5 h-cog-4 w-cog-4 shrink-0" />
      <span>{m.ask_survey_preview_notice()}</span>
    </p>
  );
}

/**
 * The post-submission screen — the payload of story #1284. Renders the author's
 * `completion_message` with `whitespace-pre-line` so its line breaks read as
 * written, or the platform default when the field is empty.
 *
 * React escapes the message, so newlines are the ONLY markup this can produce.
 * That is precisely why the field needs no HTML sanitizer: script content
 * cannot execute here by construction, not by filtering.
 */
export function PreviewCompletionPanel({
  completionMessage,
  onRestart,
}: {
  readonly completionMessage: string;
  readonly onRestart: () => void;
}): ReactElement {
  const message =
    completionMessage.trim() !== ""
      ? completionMessage
      : m.ask_survey_preview_completion_default();

  return (
    <section
      aria-labelledby="ask-preview-completion-heading"
      className="rounded-xl border border-cog-border bg-cog-surface p-cog-6 text-center shadow-cog-e1"
    >
      <CheckCircle2
        aria-hidden="true"
        className="mx-auto mb-cog-3 h-cog-7 w-cog-7 text-cog-success-600 dark:text-cog-success-dark"
      />
      <h2
        id="ask-preview-completion-heading"
        className="mb-cog-2 text-heading-lg font-semibold text-cog-text-primary"
      >
        {m.ask_survey_preview_completion_heading()}
      </h2>
      <p
        data-i18n-allow="data"
        className="whitespace-pre-line text-body-md text-cog-text-secondary"
      >
        {message}
      </p>
      <div className="mt-cog-5">
        <Button type="button" variant="secondary" onClick={onRestart}>
          {m.ask_survey_preview_restart_cta()}
        </Button>
      </div>
    </section>
  );
}

/** The survey's title and description, shared by both preview modes. */
function PreviewHeader({ survey }: { readonly survey: SurveyDTO }): ReactElement {
  return (
    <header className="mb-cog-5">
      <h1
        data-i18n-allow="data"
        className="text-display-lg font-semibold text-cog-text-primary"
      >
        {survey.title}
      </h1>
      {survey.description !== undefined && survey.description !== "" && (
        <p
          data-i18n-allow="data"
          className="mt-cog-2 text-body-md text-cog-text-secondary"
        >
          {survey.description}
        </p>
      )}
    </header>
  );
}

/**
 * What every preview leads with, in both modes: the "nothing is saved" notice
 * and the survey's own title.
 *
 * Shared for the same reason `PreviewFlowRunner` takes its header as a prop
 * rather than building one — a change to what a preview says about itself must
 * land on the single-page scroll and the branched walk at the same time, not on
 * whichever one someone remembered.
 */
function PreviewBanner({ survey }: { readonly survey: SurveyDTO }): ReactElement {
  return (
    <>
      <PreviewNotice />
      <PreviewHeader survey={survey} />
    </>
  );
}

/** The post-submission screen, in both modes: the notice plus the panel. */
function PreviewCompletion({
  survey,
  onRestart,
}: {
  readonly survey: SurveyDTO;
  readonly onRestart: () => void;
}): ReactElement {
  return (
    <>
      <PreviewNotice />
      <PreviewCompletionPanel
        completionMessage={survey.completion_message ?? ""}
        onRestart={onRestart}
      />
    </>
  );
}

/**
 * A survey with no questions yet.
 *
 * Rendered ABOVE the mode fork, so "there is nothing to ask you" is one screen
 * with one wording rather than a case each mode answers separately. The
 * branched runner used to fall through to its completion panel here and tell a
 * respondent their response was received when they had submitted nothing.
 */
function PreviewEmptyState(): ReactElement {
  return (
    <div className="rounded-xl border border-cog-border bg-cog-surface p-cog-6 text-center">
      <h2 className="mb-cog-1 text-heading-lg font-semibold text-cog-text-primary">
        {m.ask_survey_detail_questions_empty_heading()}
      </h2>
      <p className="text-body-md text-cog-text-secondary">
        {m.ask_survey_preview_empty_body()}
      </p>
    </div>
  );
}

/**
 * The interactive body, mounted once the survey and its questions have loaded.
 * Split out so `usePreviewAnswers` is seeded exactly once from a settled
 * question list rather than from a loading placeholder.
 */
function SurveyPreviewBody({
  survey,
  questions,
  sections,
}: {
  readonly survey: SurveyDTO;
  readonly questions: readonly QuestionDTO[];
  readonly sections: readonly SectionSummary[];
}): ReactElement {
  const state = usePreviewAnswers(questions);
  const entries = buildEditorEntries(questions, sections);
  // buildEditorEntries guarantees the top-level order is exactly
  // [implicit run] + [sections], so partitioning here cannot reorder anything.
  const implicitQuestions = entries.flatMap((entry) =>
    entry.kind === "question" ? [entry.question] : [],
  );
  const sectionEntries = entries.flatMap((entry) =>
    entry.kind === "section" ? [entry] : [],
  );
  const containerRef = useRef<HTMLDivElement>(null);

  // Move focus to the first question that failed validation. Without this a
  // keyboard or screen-reader user hears the summary alert but has no idea
  // WHICH question to go back to in a long survey.
  useEffect(() => {
    if (state.firstInvalidId === null) return;
    const card = containerRef.current?.querySelector(
      `[data-question-id="${state.firstInvalidId}"]`,
    );
    const focusable = card?.querySelector<HTMLElement>(
      "input, textarea, select, button",
    );
    focusable?.focus();
    // `failedAttempts` is in the deps on purpose: a second submit that fails on
    // the SAME question changes neither the id nor `showSummary`, so without it
    // this effect would not re-run and focus would never move.
  }, [state.firstInvalidId, state.showSummary, state.failedAttempts]);

  if (state.submitted) {
    return <PreviewCompletion survey={survey} onRestart={state.restart} />;
  }

  // A 1-based counter across the whole survey, incremented in render order so
  // numbering matches what the editor shows. Derived, never stored.
  let number = 0;

  return (
    <div ref={containerRef}>
      <PreviewBanner survey={survey} />

      {/* An empty survey never reaches here — the route renders
          PreviewEmptyState above the mode fork, so both previews say the
          same thing about a survey with no questions. */}
      {state.showSummary && (
        <p
          role="alert"
          className="mb-cog-4 rounded-lg border border-cog-danger-200 bg-cog-danger-50 px-cog-4 py-cog-3 text-body-sm text-cog-danger-700 dark:border-transparent dark:bg-cog-danger-dark-bg dark:text-cog-danger-dark"
        >
          {m.ask_survey_preview_validation_summary()}
        </p>
      )}

      <div className="flex flex-col gap-cog-5">
        {/* The implicit run — every question with no section — is emitted
            FIRST by buildEditorEntries and rendered as ONE list, with no
            section chrome of any kind. Wrapping each standalone question in
            its own <ol> instead would tell assistive tech there were N
            one-item lists rather than a run of N questions. */}
        {implicitQuestions.length > 0 && (
          <ol
            aria-label={m.ask_survey_editor_implicit_run_region_label()}
            className="flex list-none flex-col gap-cog-4 p-cog-0"
          >
            {implicitQuestions.map((q) => {
              number += 1;
              return (
                <PreviewQuestionCard
                  key={q.id}
                  question={q}
                  number={number}
                  answer={state.answers[q.id] ?? initialAnswer(q)}
                  onChange={(next) => state.setAnswer(q.id, next)}
                  error={state.errors[q.id]}
                />
              );
            })}
          </ol>
        )}

        {sectionEntries.map((entry) => {
          const headingId = `preview-section-${entry.section.id}`;
          return (
            <section key={entry.section.id} aria-labelledby={headingId}>
              <h2
                id={headingId}
                data-i18n-allow="data"
                className="text-heading-lg font-semibold text-cog-text-primary"
              >
                {entry.section.title}
              </h2>
              {entry.section.description !== "" && (
                <p
                  data-i18n-allow="data"
                  className="mt-cog-1 text-body-md text-cog-text-secondary"
                >
                  {entry.section.description}
                </p>
              )}
              <ol className="mt-cog-3 flex list-none flex-col gap-cog-4 p-cog-0">
                {entry.questions.map((q) => {
                  number += 1;
                  return (
                    <PreviewQuestionCard
                      key={q.id}
                      question={q}
                      number={number}
                      answer={state.answers[q.id] ?? initialAnswer(q)}
                      onChange={(next) => state.setAnswer(q.id, next)}
                      error={state.errors[q.id]}
                    />
                  );
                })}
              </ol>
            </section>
          );
        })}
      </div>

      <div className="mt-cog-6 flex justify-end">
        <Button type="button" onClick={state.submit}>
          {m.ask_survey_preview_submit_cta()}
        </Button>
      </div>
    </div>
  );
}

export function SurveyPreviewRoute(): ReactElement {
  const { id } = useParams<{ id: string }>();
  const surveyId = id ?? "";
  const detail = useSurveyDetail(surveyId);

  if (detail.state === "loading") {
    return (
      <PreviewShell surveyId={surveyId}>
        <div role="status" aria-live="polite" aria-busy="true" className="flex flex-col gap-cog-3">
          <span className="sr-only">{m.ask_surveys_loading()}</span>
          <Skeleton className="h-cog-6 w-cog-19" />
          <Skeleton className="h-cog-11 w-full" />
          <Skeleton className="h-cog-11 w-full" />
        </div>
      </PreviewShell>
    );
  }

  if (detail.state === "error") {
    return (
      <PreviewShell surveyId={surveyId}>
        <SurveysRetryAlert onRetry={detail.refetch} />
      </PreviewShell>
    );
  }

  const { survey, questions, sections } = detail;

  // One combined gate, matching SurveyDetailRoute: mounting on questions alone
  // would render the survey then flash section headings in a moment later.
  if (questions.state === "loading" || sections.state === "loading") {
    return (
      <PreviewShell surveyId={surveyId}>
        <div role="status" aria-live="polite" aria-busy="true" className="flex flex-col gap-cog-3">
          <span className="sr-only">{m.ask_surveys_loading()}</span>
          <Skeleton className="h-cog-11 w-full" />
          <Skeleton className="h-cog-11 w-full" />
        </div>
      </PreviewShell>
    );
  }

  if (questions.state === "error") {
    return (
      <PreviewShell surveyId={surveyId}>
        <SurveysRetryAlert onRetry={questions.refetch} />
      </PreviewShell>
    );
  }

  if (sections.state === "error") {
    return (
      <PreviewShell surveyId={surveyId}>
        <SurveysRetryAlert onRetry={sections.refetch} />
      </PreviewShell>
    );
  }

  // A survey with no questions is answered ONCE, above the mode fork. Leaving
  // it to each mode is what let the branched runner reach its completion panel
  // for an empty survey and report a response that was never submitted.
  if (questions.questions.length === 0) {
    return (
      <PreviewShell surveyId={surveyId}>
        <PreviewBanner survey={survey} />
        <PreviewEmptyState />
      </PreviewShell>
    );
  }

  // WHICH PREVIEW THE SURVEY GETS (story #2302). A survey that routes cannot be
  // previewed on one page — there is no way to "skip past" a question that is
  // already on screen — so a branched survey walks one question at a time. An
  // unbranched one keeps #1284's single-page scroll exactly as it shipped,
  // rather than paying a click per question for a feature it does not use.
  //
  // The switch lives HERE, not inside SurveyPreviewBody, so that only one of
  // the two ever mounts: both own answer state through usePreviewAnswers, and
  // rendering the runner from inside the body would leave a second, invisible
  // copy of that state seeded and updating alongside the real one.
  if (hasAnyBranch(questions.questions)) {
    return (
      <PreviewShell surveyId={surveyId}>
        <PreviewFlowRunner
          key={survey.id}
          header={<PreviewBanner survey={survey} />}
          questions={questions.questions}
          sections={sections.sections}
          renderCompletion={(onRestart) => (
            <PreviewCompletion survey={survey} onRestart={onRestart} />
          )}
        />
      </PreviewShell>
    );
  }

  return (
    <PreviewShell surveyId={surveyId}>
      <SurveyPreviewBody
        key={survey.id}
        survey={survey}
        questions={questions.questions}
        sections={sections.sections}
      />
    </PreviewShell>
  );
}


