/**
 * SurveysCreateRoute — the full-page "Create survey" flow at
 * /ask/surveys/new. Step 1 is a 3-card chooser — Manual (#1277), Generate
 * with AI (#1278), and Import from CSV (#1279) are all active cards. Step 2
 * ("manual", #1277) is a title+description form; step "ai" (#1278) is the
 * full AI-generation form; step "csv" (#1279) is the full CSV-import form.
 * `step` is local useState, not a second route/URL segment — a lightweight
 * in-page wizard matching the single `createpage` source artboard (docs/
 * design/ask-survey-create.md §2). Nests under AskLayout like every other
 * ask-mfe route (registered in AskApp.tsx) — the shared platform Topbar +
 * AskNav sidebar persist; only this component's own content swaps between
 * steps.
 *
 * Steps "ai" and "csv" are REAL structural branches (docs/design/
 * ask-ai-survey-generation.md flag 4, mirrored by docs/design/
 * ask-csv-import.md): SurveyAIForm/SurveyCsvImportForm render as the ENTIRE
 * content, bypassing the shared 1100px wrapper + persistent "Back to
 * Surveys" link + "Create New Survey" <h1> that "choose"/"manual" keep
 * exactly as #1277 shipped them — each owns its own narrower wrapper, its
 * own "Back to Options" control, and its own hero. Each is however still
 * wrapped in the SAME bounded `flex min-h-cog-0 flex-1 flex-col overflow-y-auto`
 * scroller the "choose"/"manual" branch below uses (QA scroll-void fix,
 * story #1279) — this route owns the scroll boundary for every step
 * uniformly; the form components themselves stay non-scrolling content.
 *
 * Two separate exits, two separate destinations for "choose"/"manual": the
 * persistent "Back to Surveys" link leaves the flow entirely (navigates to
 * the list); step 2's "Cancel" button only returns to step 1's chooser,
 * staying on /ask/surveys/new. Steps "ai" and "csv" instead each offer two
 * ROUTES to the SAME destination (their own "Back to Options" top control
 * and their own footer "Cancel") — both return to "choose" (docs/design/
 * ask-ai-survey-generation.md flag 5).
 *
 * Focus management on step transition (design.md a11y + brief §6.2):
 * "choose" -> "manual" moves focus to the step-2 <h2>; "choose" -> "ai"
 * moves focus to SurveyAIForm's own <h1> (handled inside SurveyAIForm
 * itself, since that step owns its own heading rather than a
 * parent-supplied one); "choose" -> "csv" moves focus to
 * SurveyCsvImportForm's own <h1> via `csvHeadingRef`, which THIS route owns
 * and passes down (mirroring SurveyManualForm's `headingRef` prop pattern,
 * not SurveyAIForm's self-contained one — SurveyCsvImportForm doesn't need
 * its own mount effect since this route's existing step-transition effect
 * already covers it uniformly). Returning to "choose" (via any step's
 * Cancel/Back) restores focus to whichever chooser card originally
 * triggered the transition. Skipped on the very first render (nothing to
 * restore focus to yet, and the natural tab order already starts at the
 * back link).
 */
import { type ReactElement, useEffect, useRef, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { ArrowLeft } from "@omnicore-platform/ui/icons";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { SurveyCreateChooser } from "../components/SurveyCreateChooser";
import { SurveyManualForm } from "../components/SurveyManualForm";
import { SurveyAIForm } from "../components/SurveyAIForm";
import { SurveyCsvImportForm } from "../components/SurveyCsvImportForm";
import { useToast } from "@omnicore-platform/ui/toast";

type Step = "choose" | "manual" | "ai" | "csv";

export function SurveysCreateRoute(): ReactElement {
  const [step, setStep] = useState<Step>("choose");
  const navigate = useNavigate();
  const toast = useToast();
  const manualCardRef = useRef<HTMLButtonElement>(null);
  const aiCardRef = useRef<HTMLButtonElement>(null);
  const importCardRef = useRef<HTMLButtonElement>(null);
  const stepHeadingRef = useRef<HTMLHeadingElement>(null);
  const csvHeadingRef = useRef<HTMLHeadingElement>(null);
  const isFirstRender = useRef(true);
  // Remembers which step is being LEFT on a transition back to "choose", so
  // the effect below knows which card to restore focus to — "manual", "ai",
  // and "csv" each have their own Cancel/Back control, and only one of the
  // three chooser cards was ever the actual trigger for a given round trip.
  const returningFromRef = useRef<"manual" | "ai" | "csv" | null>(null);

  useEffect(() => {
    if (isFirstRender.current) {
      isFirstRender.current = false;
      return;
    }
    if (step === "manual") {
      stepHeadingRef.current?.focus();
    } else if (step === "csv") {
      csvHeadingRef.current?.focus();
    } else if (step === "choose") {
      if (returningFromRef.current === "ai") {
        aiCardRef.current?.focus();
      } else if (returningFromRef.current === "csv") {
        importCardRef.current?.focus();
      } else {
        manualCardRef.current?.focus();
      }
      returningFromRef.current = null;
    }
  }, [step]);

  function returnToChoose(fromStep: "manual" | "ai" | "csv"): void {
    returningFromRef.current = fromStep;
    setStep("choose");
  }

  /**
   * QA scroll-void fix (story #1279): QA reported the page scrolling past
   * the footer into empty space. Root cause was a structural asymmetry —
   * the "choose"/"manual" step below (and SurveysListRoute's root) renders
   * inside a bounded `flex min-h-cog-0 flex-1 flex-col overflow-y-auto`
   * scroller, but "ai"/"csv" used to render their form DIRECTLY as
   * `<main>`'s (AskLayout's) child with no bounded scroller of its own,
   * letting `<main>`'s box grow past the real content. Both branches below
   * now wrap their form in that SAME bounded scroller (no px/py on the
   * wrapper — each form already carries its own padding).
   *
   * The SCROLL responsibility lives on THIS wrapper, NOT on either form
   * component's own outer div: an earlier attempt to put `flex-1 min-h-cog-0
   * overflow-y-auto` directly on a form's own outer div broke the page —
   * the CARD right below it sets `overflow-hidden` (for its rounded
   * corners/gradient overlay), and combined with a flex-shrinking ancestor
   * the CSS flex-item "automatic minimum size" rule (auto -> 0 when
   * overflow isn't `visible`) let the browser shrink the card below its
   * content height and SILENTLY CLIP the footer. Each form's own outer div
   * instead carries `shrink-0` — a non-shrinking child of THIS wrapper — so
   * the browser always keeps it (and its overflow-hidden card) at full
   * content height; this wrapper scrolls when that content genuinely
   * exceeds the viewport. Do not add `flex-1`/`overflow-y-auto` back onto
   * either form's own outer div without re-verifying in a real browser
   * first.
   */
  if (step === "ai") {
    return (
      // Bounded scroller — rationale above.
      <div className="flex min-h-cog-0 flex-1 flex-col overflow-y-auto bg-cog-canvas">
        <SurveyAIForm
          onCancel={() => returnToChoose("ai")}
          onGenerated={(surveyId, questionCount) => {
            // Generation is async and can take minutes, so landing in the
            // editor is otherwise the ONLY signal it finished — and a Draft
            // full of questions looks the same whether the worker wrote them
            // or they were already there. Confirm the outcome and its size,
            // mirroring the CSV branch below; the toast is mounted at the
            // AskApp root, so it survives the navigate().
            toast.success(m.ask_surveys_ai_generate_success({ count: questionCount }));
            navigate(`/ask/surveys/${surveyId}`);
          }}
        />
      </div>
    );
  }

  if (step === "csv") {
    return (
      // Bounded scroller — rationale above.
      <div className="flex min-h-cog-0 flex-1 flex-col overflow-y-auto bg-cog-canvas">
        <SurveyCsvImportForm
          headingRef={csvHeadingRef}
          onCancel={() => returnToChoose("csv")}
          onImported={(survey) => {
            // Bug-fix (story #1279 QA): confirm to the user how many
            // questions were actually imported — the count is only known
            // here, on the successful response, and the toast (mounted at
            // the AskApp root) survives the navigate() below.
            toast.success(
              m.ask_surveys_csv_import_success({ count: survey.question_count }),
            );
            navigate(`/ask/surveys/${survey.id}`);
          }}
        />
      </div>
    );
  }

  return (
    <div className="flex min-h-cog-0 flex-1 flex-col overflow-y-auto bg-cog-canvas px-cog-4 py-cog-6 sm:px-cog-5">
      <div className="mx-auto w-full max-w-cog-46">
        <Link
          to="/ask/surveys"
          className={[
            "inline-flex items-center gap-cog-2 text-body-md font-medium text-cog-text-secondary",
            "hover:text-cog-text-primary transition-colors duration-standard",
            "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus",
            "rounded-md",
          ].join(" ")}
        >
          <ArrowLeft aria-hidden="true" className="h-cog-4 w-cog-4 rtl:-scale-x-100" />
          {m.ask_surveys_create_back_cta()}
        </Link>

        <h1 className="mb-cog-5 mt-cog-5 text-display-lg font-semibold text-cog-text-primary">
          {m.ask_surveys_create_page_title()}
        </h1>

        {step === "choose" ? (
          <SurveyCreateChooser
            onSelectManual={() => setStep("manual")}
            manualCardRef={manualCardRef}
            onSelectAI={() => setStep("ai")}
            aiCardRef={aiCardRef}
            onSelectImport={() => setStep("csv")}
            importCardRef={importCardRef}
          />
        ) : (
          <SurveyManualForm
            headingRef={stepHeadingRef}
            onCancel={() => returnToChoose("manual")}
            onCreated={(survey) => navigate(`/ask/surveys/${survey.id}`)}
          />
        )}
      </div>
    </div>
  );
}


