/**
 * SurveysListRoute — the Ask home: a search + sort + grid/list toolbar over
 * a status-tab-filterable card grid or list table (fix/ask-survey-list-ui,
 * design spec §2.9).
 *
 * Orchestration only — every filter/sort/search operation is a SERVER
 * round-trip (ask-bff's `?status=`/`?q=`/`?sort=`/`?order=`, story
 * behind #1276/#1277's Survey Creation epic). This route never filters or
 * sorts client-side; it only maps its local UI state (debounced search
 * text, the chosen SurveySortOption, the active status tab, the grid/list
 * view mode) into `ListSurveysParams` for `useSurveys`.
 *
 * View-mode-specific behavior (design spec §2.4): the status tabs and
 * their filter apply ONLY in grid view. Switching to list view shows every
 * survey unfiltered; the previously-active tab is kept in local state (not
 * reset) so switching back to grid restores it — there's no tab UI in list
 * mode to represent a non-"all" filter, so silently keeping it applied
 * server-side would leave the list showing fewer rows with no visible
 * explanation.
 *
 * Empty states: zero org-wide total -> SurveysEmptyHero; a non-empty search
 * with zero matches -> the inline no-match panel; a zero-total status tab
 * (grid view, no search) -> the inline tab-empty panel, whose Clear action
 * resets the tab to "all". Search takes precedence when both are active
 * (it's the more specific, most-recently-touched control).
 */

import { type ReactElement, useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { Plus, Search } from "@omnicore-platform/ui/icons";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { useSurveys } from "../hooks/useSurveys";
import { useSurveyViewMode } from "../state/useSurveyViewMode";
import { SurveyCard } from "../components/SurveyCard";
import { SurveyCardSkeleton } from "../components/SurveyCardSkeleton";
import { SurveyListTable, SurveyListRowSkeleton } from "../components/SurveyListTable";
import { ConfirmDeleteSurveyDialog } from "../components/ConfirmDeleteSurveyDialog";
import { useSurveyActions } from "../hooks/useSurveyActions";
import { useToast } from "@omnicore-platform/ui/toast";
import type { SurveyDTO } from "../api/surveys";
import { SurveysToolbar, type SurveySortOption } from "../components/SurveysToolbar";
import { SurveyStatusTabs, type SurveyStatusTab } from "../components/SurveyStatusTabs";
import { SurveysRetryAlert } from "../components/SurveysRetryAlert";
import { SurveysEmptyHero } from "../components/SurveysEmptyHero";
import { SurveyListEmptyPanel } from "../components/SurveyListEmptyPanel";
import type {
  FilterableSurveyStatus,
  ListSurveysParams,
  SurveySortKey,
  SurveySortOrder,
} from "../api/surveys";

const SKELETON_COUNT = 6;
const SEARCH_DEBOUNCE_MS = 300;

type StatusTabKey = "all" | FilterableSurveyStatus;

function isStatusTabKey(v: string): v is StatusTabKey {
  return v === "all" || v === "draft" || v === "published" || v === "closed";
}

const SORT_TO_SERVER: Record<
  SurveySortOption,
  { readonly sort: SurveySortKey; readonly order: SurveySortOrder }
> = {
  newest: { sort: "created_at", order: "desc" },
  oldest: { sort: "created_at", order: "asc" },
  status: { sort: "status", order: "asc" },
  title_asc: { sort: "title", order: "asc" },
  title_desc: { sort: "title", order: "desc" },
};

export function SurveysListRoute(): ReactElement {
  const navigate = useNavigate();
  const { mode: viewMode, setMode: setViewMode } = useSurveyViewMode();

  const [search, setSearch] = useState("");
  const [debouncedSearch, setDebouncedSearch] = useState("");
  const [sort, setSort] = useState<SurveySortOption>("newest");
  const [activeTab, setActiveTab] = useState<StatusTabKey>("all");

  // Debounce the search box -> the server round-trip. Cleared on every
  // keystroke so only the last pending timer ever fires.
  useEffect(() => {
    const handle = setTimeout(
      () => setDebouncedSearch(search),
      SEARCH_DEBOUNCE_MS,
    );
    return () => clearTimeout(handle);
  }, [search]);

  const params = useMemo<ListSurveysParams>(() => {
    const { sort: sortKey, order } = SORT_TO_SERVER[sort];
    const status =
      viewMode === "grid" && activeTab !== "all" ? activeTab : undefined;
    return { search: debouncedSearch, sort: sortKey, order, status };
  }, [debouncedSearch, sort, viewMode, activeTab]);

  const listState = useSurveys(params);
  const toast = useToast();
  const actions = useSurveyActions();

  /**
   * The survey awaiting delete confirmation, or null. Holds the whole DTO
   * rather than an id so the dialog can quote the title and the response count
   * even if the list refetches underneath it.
   */
  const [deleting, setDeleting] = useState<SurveyDTO | null>(null);

  /**
   * `refetch` only exists on the settled states. Reaching for it through a
   * narrow keeps the mutation handlers honest: a mutation can only be started
   * from a rendered card, which means the list already settled.
   */
  const refetch = listState.state === "loading" ? undefined : listState.refetch;

  async function handleDuplicate(survey: SurveyDTO): Promise<void> {
    const copy = await actions.duplicate(survey.id);
    if (copy === null) {
      toast.error(m.ask_survey_action_generic_error());
      return;
    }
    // Names the COPY, not the source — the copy is the new thing on screen,
    // and the server may have disambiguated its title.
    toast.success(m.ask_survey_duplicate_success({ title: copy.title }));
    refetch?.();
  }

  async function handleCustomize(
    survey: SurveyDTO,
    next: { icon: string; colour: string },
  ): Promise<boolean> {
    const updated = await actions.customize(survey.id, next);
    if (updated === null) {
      toast.error(m.ask_survey_action_generic_error());
      // False keeps the panel open on its own error, matching how the delete
      // dialog stays up rather than vanishing on a failed write.
      return false;
    }
    toast.success(m.ask_survey_customize_success());
    refetch?.();
    return true;
  }

  async function handleConfirmDelete(): Promise<void> {
    if (deleting === null) return;
    const removed = await actions.remove(deleting.id);
    if (removed === null) return; // the dialog shows the error and stays open
    toast.success(m.ask_survey_delete_success({ title: deleting.title }));
    setDeleting(null);
    refetch?.();
  }

  const onCreateSurvey = (): void => navigate("/ask/surveys/new");
  const onTabChange = (key: string): void => {
    if (isStatusTabKey(key)) setActiveTab(key);
  };

  const surveys = listState.state === "data" ? listState.surveys : [];
  const statusCounts =
    listState.state === "data"
      ? listState.statusCounts
      : { total: 0, draft: 0, published: 0, closed: 0 };

  const tabs: readonly SurveyStatusTab[] = [
    { key: "all", label: m.ask_surveys_tab_all(), count: statusCounts.total },
    {
      key: "draft",
      label: m.ask_survey_status_draft(),
      count: statusCounts.draft,
    },
    {
      key: "published",
      label: m.ask_survey_status_published(),
      count: statusCounts.published,
    },
    {
      key: "closed",
      label: m.ask_survey_status_closed(),
      count: statusCounts.closed,
    },
  ];

  const hasSearch = search.trim() !== "";
  const isTabFiltered = viewMode === "grid" && activeTab !== "all";

  return (
    <div className="flex min-h-cog-0 flex-1 flex-col overflow-y-auto bg-cog-canvas">
      <header className="flex flex-wrap items-start justify-between gap-cog-4 border-b border-cog-divider bg-cog-surface px-cog-5 py-cog-4-5">
        <div>
          <h1 className="text-display-lg font-semibold text-cog-text-primary">
            {m.ask_surveys_list_title()}
          </h1>
          <p className="mt-cog-1 text-body-sm text-cog-text-secondary">
            {m.ask_surveys_list_subtitle()}
          </p>
        </div>
        <button
          type="button"
          onClick={onCreateSurvey}
          className={[
            "inline-flex min-h-btn items-center gap-cog-2 rounded-md px-cog-4-5",
            "bg-cog-blue-600 text-body-md font-semibold text-white",
            "hover:-translate-y-px hover:shadow-cog-glow-brand dark:hover:shadow-cog-glow-brand-dark",
            "motion-reduce:hover:translate-y-cog-0",
            "transition-[transform,box-shadow] duration-standard",
            "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-2",
          ].join(" ")}
        >
          <Plus aria-hidden="true" className="h-cog-4 w-cog-4" />
          {m.ask_surveys_create_cta()}
        </button>
      </header>

      <div className="flex flex-1 flex-col gap-cog-5 p-cog-5">
        {listState.state === "loading" && (
          <div role="status" aria-live="polite" aria-busy="true">
            <span className="sr-only">{m.ask_surveys_loading()}</span>
            {viewMode === "grid" ? (
              <div className="grid grid-cols-[repeat(auto-fill,minmax(320px,1fr))] gap-cog-4">
                {Array.from({ length: SKELETON_COUNT }).map((_, i) => (
                  <SurveyCardSkeleton key={i} />
                ))}
              </div>
            ) : (
              <div className="overflow-hidden rounded-xl border border-cog-border">
                {Array.from({ length: SKELETON_COUNT }).map((_, i) => (
                  <SurveyListRowSkeleton key={i} />
                ))}
              </div>
            )}
          </div>
        )}

        {listState.state === "error" && (
          <SurveysRetryAlert onRetry={listState.refetch} />
        )}

        {listState.state === "data" &&
          (statusCounts.total === 0 ? (
            <SurveysEmptyHero onCreateSurvey={onCreateSurvey} />
          ) : (
            <>
              <SurveysToolbar
                search={search}
                onSearchChange={setSearch}
                sort={sort}
                onSortChange={setSort}
                viewMode={viewMode}
                onViewModeChange={setViewMode}
              />

              {viewMode === "grid" && (
                <SurveyStatusTabs
                  tabs={tabs}
                  active={activeTab}
                  onChange={onTabChange}
                />
              )}

              {viewMode === "grid" ? (
                // A single persistent tabpanel container for EVERY grid-view
                // content branch (card grid, no-match panel, tab-empty
                // panel) — the status tabs' aria-controls always points at
                // this id, so filtering/searching to zero results never
                // leaves that reference dangling.
                <div
                  id="ask-surveys-panel"
                  role="tabpanel"
                  tabIndex={0}
                  aria-labelledby={`ask-surveys-tab-${activeTab}`}
                >
                  {surveys.length === 0 ? (
                    hasSearch ? (
                      <SurveyListEmptyPanel
                        icon={
                          <span
                            aria-hidden="true"
                            className="inline-flex h-cog-7 w-cog-7 items-center justify-center rounded-md bg-cog-surface-muted text-cog-text-tertiary"
                          >
                            <Search aria-hidden="true" className="h-cog-4-5 w-cog-4-5" />
                          </span>
                        }
                        heading={m.ask_surveys_no_match()}
                        body={m.ask_surveys_no_match_help()}
                        ctaLabel={m.ask_surveys_clear_search_cta()}
                        onClear={() => setSearch("")}
                      />
                    ) : isTabFiltered ? (
                      <SurveyListEmptyPanel
                        heading={m.ask_surveys_tab_empty_heading()}
                        body={m.ask_surveys_tab_empty_body()}
                        ctaLabel={m.ask_surveys_tab_empty_clear_cta()}
                        onClear={() => setActiveTab("all")}
                      />
                    ) : null
                  ) : (
                    /*
                      `min-w-cog-0` on each <li>: a grid item's `min-width: auto`
                      resolves to its MIN-CONTENT size, so one long unbreakable
                      title widens the whole track and pushes the grid
                      off-screen. Stated explicitly rather than relying on the
                      card's own `overflow-hidden` to pin it to 0 as a side
                      effect of clipping — the constraint belongs to the grid
                      item, and reading it off a descendant's paint behaviour
                      is how it silently regresses.
                    */
                    <ul className="grid grid-cols-[repeat(auto-fill,minmax(320px,1fr))] gap-cog-4">
                      {surveys.map((s) => (
                        <li key={s.id} className="flex min-w-cog-0">
                          <SurveyCard
                            survey={s}
                            onDuplicate={() => void handleDuplicate(s)}
                            onDelete={() => setDeleting(s)}
                            onCustomize={(next) => handleCustomize(s, next)}
                            isCustomizeBusy={actions.pendingId === s.id}
                            customizeError={actions.lastErrorId === s.id ? actions.lastError : null}
                          />
                        </li>
                      ))}
                    </ul>
                  )}
                </div>
              ) : surveys.length === 0 ? (
                hasSearch ? (
                  <SurveyListEmptyPanel
                    icon={
                      <span
                        aria-hidden="true"
                        className="inline-flex h-cog-7 w-cog-7 items-center justify-center rounded-md bg-cog-surface-muted text-cog-text-tertiary"
                      >
                        <Search aria-hidden="true" className="h-cog-4-5 w-cog-4-5" />
                      </span>
                    }
                    heading={m.ask_surveys_no_match()}
                    body={m.ask_surveys_no_match_help()}
                    ctaLabel={m.ask_surveys_clear_search_cta()}
                    onClear={() => setSearch("")}
                  />
                ) : null
              ) : (
                <SurveyListTable
                  surveys={surveys}
                  onDuplicate={(s) => void handleDuplicate(s)}
                  onDelete={(s) => setDeleting(s)}
                  onCustomize={(s, next) => handleCustomize(s, next)}
                  customizePendingId={actions.pendingId}
                  customizeError={actions.lastError}
                  customizeErrorId={actions.lastErrorId}
                />
              )}
            </>
          ))}
      </div>

      {/* Mounted/unmounted by `deleting` rather than holding its own `open`
          state, so the route owns when it closes and can keep it up while the
          request is in flight. */}
      {deleting !== null && (
        <ConfirmDeleteSurveyDialog
          title={deleting.title}
          responseCount={deleting.response_count}
          isBusy={actions.pendingId === deleting.id}
          error={actions.lastError}
          onConfirm={() => void handleConfirmDelete()}
          onCancel={() => setDeleting(null)}
        />
      )}
    </div>
  );
}


