// Single source of truth for the three Ask sidebar sub-routes (#1274).
//
// Both the sidebar (AskLayout's NAV_ITEMS) and the router (AskApp's <Route>
// table) derive their paths + placeholder content from this one array, so the
// nav links and the route declarations cannot drift apart as the real
// Surveys / Analytics / Settings surfaces replace the placeholders in later
// stories. Consolidates what were three structurally identical route
// components + two independently-maintained path lists (PR #1693 review).
//
// `segment` is the UNPREFIXED route path — AskApp mounts each as `/${segment}`
// (react-router resolves it against the parent `/ask/*` match / standalone
// basename). The sidebar prepends `/ask/` for its NavLink `to` targets, since
// the federated mount has no router basename (see AskLayout's NAV_ITEMS
// comment + the no-bare-ask-links guard).

import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import {
  BarChart3,
  ClipboardList,
  Settings,
  type LucideIcon,
} from "@omnicore-platform/ui/icons";

export interface AskNavRoute {
  /** Unprefixed route segment, e.g. "surveys" (mounted at /ask/surveys). */
  readonly segment: string;
  /** Sidebar link label (paraglide message fn, called lazily at render). */
  readonly label: () => string;
  /** Sidebar link icon — rendered in both the expanded and collapsed AskNav rail. */
  readonly icon: LucideIcon;
  /** Shared by the PlaceholderHero <h1> id and its section aria-labelledby. */
  readonly headingId: string;
  readonly heading: () => string;
  readonly body: () => string;
}

export const ASK_NAV_ROUTES: readonly AskNavRoute[] = [
  {
    segment: "surveys",
    label: m.ask_nav_surveys,
