/**
 * SurveyPreviewRoute — `/ask/surveys/:id/preview` (story #1284).
 *
 * The respondent's-eye view of a survey: sections as headings with their
 * descriptions, questions in survey order with genuinely interactive controls,
 * required-answer validation on Submit, and the author's **completion message**
 * on the post-submission screen (falling back to the platform default when the
 * author hasn't set one). This is the surface that makes #1284's journey steps
 * 4-6 real.
 *
 * **Nothing is persisted.** No `ResponseService.Submit`, no POST to the public
 * respondent routes (which are 501 stubs anyway), no `ask.responses` row. A
 * preview that recorded a response would inflate `Survey.response_count` and
 * corrupt the per-survey analytics epic #1291 builds on it. The banner says so
 * plainly rather than leaving the respondent-facing fiction ambiguous.
 *
 * **Why this route exists here at all.** A sweep of every `module: ask` issue
 * found no story that owns survey preview — #1286 publishes and #1287 generates
 * a deployment URL, but neither builds a viewing surface. Rather than ship a
 * completion-message field whose effect an author cannot see, preview lands
 * with the field that needs it. It also retires the *Preview* half of
 * divergence 3 in docs/design/ask-survey-editor.md ("no Preview / Publish
 * Survey / kebab in the editor header"); Publish stays absent for #1286.
 *
 * Ordering comes from `buildEditorEntries`, NOT a second implementation. That
 * algorithm is already duplicated between ask-svc and this MFE and the two are
 * required to agree exactly, including the `(position, id)` section tiebreak —
 * a third copy here would be a third thing to keep in step.
 */

import { useEffect, useRef, type ReactElement } from "react";
import { Link, useParams } from "react-router-dom";
import { ArrowLeft, CheckCircle2, Info } from "@omnicore-platform/ui/icons";
import { Button, Skeleton } from "@omnicore-platform/ui";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { PreviewFlowRunner } from "../components/preview/PreviewFlowRunner";
import { PreviewQuestionCard } from "../components/preview/PreviewQuestionCard";
import { SurveysRetryAlert } from "../components/SurveysRetryAlert";
import { usePreviewAnswers } from "../hooks/usePreviewAnswers";
import { useSurveyDetail } from "../hooks/useSurveyDetail";
import { buildEditorEntries } from "../lib/buildEditorEntries";
import { initialAnswer } from "../lib/previewAnswers";
import { hasAnyBranch } from "../lib/surveyTraversal";
import type { QuestionDTO } from "../api/questions";
import type { SectionSummary } from "../api/sections";
import type { SurveyDTO } from "../api/surveys";

/** The one scroll container every state of this route renders into. */
function PreviewShell({
  children,
  surveyId,
}: {
  readonly children: React.ReactNode;
  readonly surveyId: string;
}): ReactElement {
  return (
    <div className="min-h-cog-0 flex-1 overflow-y-auto px-cog-5 py-cog-6">
      <Link
        to={`/ask/surveys/${surveyId}`}
        className="mb-cog-4 inline-flex w-fit items-center gap-cog-2 rounded-md text-body-md font-medium text-cog-text-secondary transition-colors duration-standard hover:text-cog-text-primary focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus"
      >
        <ArrowLeft aria-hidden="true" className="h-cog-4 w-cog-4 rtl:-scale-x-100" />
        {m.ask_survey_preview_back_cta()}
      </Link>
      {/* max-w keeps the respondent column readable rather than stretching a
          question across a 1440px canvas. */}
      <div className="mx-auto max-w-cog-feed">{children}</div>
    </div>
  );
}

/** The persistent "this is a preview" banner. */
function PreviewNotice(): ReactElement {
  return (
    <p className="mb-cog-5 flex items-start gap-cog-2 rounded-lg border border-cog-blue-100 bg-cog-blue-50 px-cog-4 py-cog-3 text-body-sm text-cog-blue-700 dark:border-transparent dark:bg-cog-blue-950 dark:text-cog-blue-300">
      <Info aria-hidden="true" className="mt-cog-0-5 h-cog-4 w-cog-4 shrink-0" />
      <span>{m.ask_survey_preview_notice()}</span>
    </p>
  );
}

/**
 * The post-submission screen — the payload of story #1284. Renders the author's
 * `completion_message` with `whitespace-pre-line` so its line breaks read as
 * written, or the platform default when the field is empty.
 *
 * React escapes the message, so newlines are the ONLY markup this can produce.
 * That is precisely why the field needs no HTML sanitizer: script content
 * cannot execute here by construction, not by filtering.
 */
export function PreviewCompletionPanel({
  completionMessage,
  onRestart,
}: {
  readonly completionMessage: string;
  readonly onRestart: () => void;
}): ReactElement {
  const message =
    completionMessage.trim() !== ""
      ? completionMessage
      : m.ask_survey_preview_completion_default();

  return (
    <section
      aria-labelledby="ask-preview-completion-heading"
      className="rounded-xl border border-cog-border bg-cog-surface p-cog-6 text-center shadow-cog-e1"
    >
      <CheckCircle2
        aria-hidden="true"
        className="mx-auto mb-cog-3 h-cog-7 w-cog-7 text-cog-success-600 dark:text-cog-success-dark"
      />
      <h2
        id="ask-preview-completion-heading"
        className="mb-cog-2 text-heading-lg font-semibold text-cog-text-primary"
      >
        {m.ask_survey_preview_completion_heading()}
      </h2>
      <p
        data-i18n-allow="data"
        className="whitespace-pre-line text-body-md text-cog-text-secondary"
      >
        {message}
      </p>
      <div className="mt-cog-5">
        <Button type="button" variant="secondary" onClick={onRestart}>
          {m.ask_survey_preview_restart_cta()}
        </Button>
      </div>
    </section>
  );
}

/** The survey's title and description, shared by both preview modes. */
function PreviewHeader({ survey }: { readonly survey: SurveyDTO }): ReactElement {
  return (
    <header className="mb-cog-5">
      <h1
        data-i18n-allow="data"
        className="text-display-lg font-semibold text-cog-text-primary"
      >
        {survey.title}
      </h1>
      {survey.description !== undefined && survey.description !== "" && (
        <p
          data-i18n-allow="data"
          className="mt-cog-2 text-body-md text-cog-text-secondary"
        >
          {survey.description}
        </p>
      )}
    </header>
  );
}

/**
 * What every preview leads with, in both modes: the "nothing is saved" notice
 * and the survey's own title.
 *
 * Shared for the same reason `PreviewFlowRunner` takes its header as a prop
 * rather than building one — a change to what a preview says about itself must
 * land on the single-page scroll and the branched walk at the same time, not on
 * whichever one someone remembered.
 */
function PreviewBanner({ survey }: { readonly survey: SurveyDTO }): ReactElement {
  return (
    <>
      <PreviewNotice />
      <PreviewHeader survey={survey} />
    </>
  );
}

/** The post-submission screen, in both modes: the notice plus the panel. */
function PreviewCompletion({
  survey,
  onRestart,
}: {
  readonly survey: SurveyDTO;
  readonly onRestart: () => void;
}): ReactElement {
  return (
    <>
      <PreviewNotice />
      <PreviewCompletionPanel
        completionMessage={survey.completion_message ?? ""}
        onRestart={onRestart}
      />
    </>
  );
}

/**
 * A survey with no questions yet.
 *
 * Rendered ABOVE the mode fork, so "there is nothing to ask you" is one screen
 * with one wording rather than a case each mode answers separately. The
 * branched runner used to fall through to its completion panel here and tell a
 * respondent their response was received when they had submitted nothing.
 */
function PreviewEmptyState(): ReactElement {
  return (
    <div className="rounded-xl border border-cog-border bg-cog-surface p-cog-6 text-center">
      <h2 className="mb-cog-1 text-heading-lg font-semibold text-cog-text-primary">
        {m.ask_survey_detail_questions_empty_heading()}
      </h2>
      <p className="text-body-md text-cog-text-secondary">
        {m.ask_survey_preview_empty_body()}
      </p>
    </div>
  );
}

/**
 * The interactive body, mounted once the survey and its questions have loaded.
 * Split out so `usePreviewAnswers` is seeded exactly once from a settled
 * question list rather than from a loading placeholder.
 */
function SurveyPreviewBody({
  survey,
  questions,
  sections,
}: {
  readonly survey: SurveyDTO;
  readonly questions: readonly QuestionDTO[];
  readonly sections: readonly SectionSummary[];
}): ReactElement {
  const state = usePreviewAnswers(questions);
  const entries = buildEditorEntries(questions, sections);
  // buildEditorEntries guarantees the top-level order is exactly
  // [implicit run] + [sections], so partitioning here cannot reorder anything.
  const implicitQuestions = entries.flatMap((entry) =>
    entry.kind === "question" ? [entry.question] : [],
  );
  const sectionEntries = entries.flatMap((entry) =>
    entry.kind === "section" ? [entry] : [],
  );
  const containerRef = useRef<HTMLDivElement>(null);

  // Move focus to the first question that failed validation. Without this a
  // keyboard or screen-reader user hears the summary alert but has no idea
  // WHICH question to go back to in a long survey.
  useEffect(() => {
    if (state.firstInvalidId === null) return;
    const card = containerRef.current?.querySelector(
      `[data-question-id="${state.firstInvalidId}"]`,
    );
    const focusable = card?.querySelector<HTMLElement>(
      "input, textarea, select, button",
    );
    focusable?.focus();
    // `failedAttempts` is in the deps on purpose: a second submit that fails on
    // the SAME question changes neither the id nor `showSummary`, so without it
    // this effect would not re-run and focus would never move.
  }, [state.firstInvalidId, state.showSummary, state.failedAttempts]);

  if (state.submitted) {
    return <PreviewCompletion survey={survey} onRestart={state.restart} />;
  }

  // A 1-based counter across the whole survey, incremented in render order so
  // numbering matches what the editor shows. Derived, never stored.
  let number = 0;

  return (
    <div ref={containerRef}>
      <PreviewBanner survey={survey} />

      {/* An empty survey never reaches here — the route renders
          PreviewEmptyState above the mode fork, so both previews say the
          same thing about a survey with no questions. */}
      {state.showSummary && (
        <p
          role="alert"
          className="mb-cog-4 rounded-lg border border-cog-danger-200 bg-cog-danger-50 px-cog-4 py-cog-3 text-body-sm text-cog-danger-700 dark:border-transparent dark:bg-cog-danger-dark-bg dark:text-cog-danger-dark"
        >
          {m.ask_survey_preview_validation_summary()}
        </p>
      )}

      <div className="flex flex-col gap-cog-5">
        {/* The implicit run — every question with no section — is emitted
            FIRST by buildEditorEntries and rendered as ONE list, with no
            section chrome of any kind. Wrapping each standalone question in
            its own <ol> instead would tell assistive tech there were N
            one-item lists rather than a run of N questions. */}
        {implicitQuestions.length > 0 && (
          <ol
            aria-label={m.ask_survey_editor_implicit_run_region_label()}
            className="flex list-none flex-col gap-cog-4 p-cog-0"
          >
            {implicitQuestions.map((q) => {
              number += 1;
              return (
                <PreviewQuestionCard
                  key={q.id}
                  question={q}
                  number={number}
                  answer={state.answers[q.id] ?? initialAnswer(q)}
                  onChange={(next) => state.setAnswer(q.id, next)}
                  error={state.errors[q.id]}
                />
              );
            })}
          </ol>
        )}

        {sectionEntries.map((entry) => {
          const headingId = `preview-section-${entry.section.id}`;
          return (
            <section key={entry.section.id} aria-labelledby={headingId}>
              <h2
                id={headingId}
                data-i18n-allow="data"
                className="text-heading-lg font-semibold text-cog-text-primary"
              >
                {entry.section.title}
              </h2>
              {entry.section.description !== "" && (
                <p
                  data-i18n-allow="data"
                  className="mt-cog-1 text-body-md text-cog-text-secondary"
                >
                  {entry.section.description}
                </p>
              )}
              <ol className="mt-cog-3 flex list-none flex-col gap-cog-4 p-cog-0">
                {entry.questions.map((q) => {
                  number += 1;
                  return (
                    <PreviewQuestionCard
                      key={q.id}
                      question={q}
                      number={number}
                      answer={state.answers[q.id] ?? initialAnswer(q)}
                      onChange={(next) => state.setAnswer(q.id, next)}
                      error={state.errors[q.id]}
                    />
                  );
                })}
              </ol>
            </section>
          );
        })}
      </div>

      <div className="mt-cog-6 flex justify-end">
        <Button type="button" onClick={state.submit}>
          {m.ask_survey_preview_submit_cta()}
        </Button>
      </div>
    </div>
  );
}

export function SurveyPreviewRoute(): ReactElement {
  const { id } = useParams<{ id: string }>();
  const surveyId = id ?? "";
  const detail = useSurveyDetail(surveyId);

  if (detail.state === "loading") {
    return (
      <PreviewShell surveyId={surveyId}>
        <div role="status" aria-live="polite" aria-busy="true" className="flex flex-col gap-cog-3">
          <span className="sr-only">{m.ask_surveys_loading()}</span>
          <Skeleton className="h-cog-6 w-cog-19" />
          <Skeleton className="h-cog-11 w-full" />
          <Skeleton className="h-cog-11 w-full" />
        </div>
      </PreviewShell>
    );
  }

  if (detail.state === "error") {
    return (
      <PreviewShell surveyId={surveyId}>
        <SurveysRetryAlert onRetry={detail.refetch} />
      </PreviewShell>
    );
  }

  const { survey, questions, sections } = detail;

  // One combined gate, matching SurveyDetailRoute: mounting on questions alone
  // would render the survey then flash section headings in a moment later.
  if (questions.state === "loading" || sections.state === "loading") {
    return (
      <PreviewShell surveyId={surveyId}>
        <div role="status" aria-live="polite" aria-busy="true" className="flex flex-col gap-cog-3">
          <span className="sr-only">{m.ask_surveys_loading()}</span>
          <Skeleton className="h-cog-11 w-full" />
          <Skeleton className="h-cog-11 w-full" />
        </div>
      </PreviewShell>
    );
  }

  if (questions.state === "error") {
    return (
      <PreviewShell surveyId={surveyId}>
        <SurveysRetryAlert onRetry={questions.refetch} />
      </PreviewShell>
    );
  }

  if (sections.state === "error") {
    return (
      <PreviewShell surveyId={surveyId}>
        <SurveysRetryAlert onRetry={sections.refetch} />
      </PreviewShell>
    );
  }

  // A survey with no questions is answered ONCE, above the mode fork. Leaving
  // it to each mode is what let the branched runner reach its completion panel
  // for an empty survey and report a response that was never submitted.
  if (questions.questions.length === 0) {
    return (
      <PreviewShell surveyId={surveyId}>
        <PreviewBanner survey={survey} />
        <PreviewEmptyState />
      </PreviewShell>
    );
  }

  // WHICH PREVIEW THE SURVEY GETS (story #2302). A survey that routes cannot be
  // previewed on one page — there is no way to "skip past" a question that is
  // already on screen — so a branched survey walks one question at a time. An
  // unbranched one keeps #1284's single-page scroll exactly as it shipped,
  // rather than paying a click per question for a feature it does not use.
  //
  // The switch lives HERE, not inside SurveyPreviewBody, so that only one of
  // the two ever mounts: both own answer state through usePreviewAnswers, and
  // rendering the runner from inside the body would leave a second, invisible
  // copy of that state seeded and updating alongside the real one.
  if (hasAnyBranch(questions.questions)) {
    return (
      <PreviewShell surveyId={surveyId}>
        <PreviewFlowRunner
          key={survey.id}
          header={<PreviewBanner survey={survey} />}
          questions={questions.questions}
          sections={sections.sections}
          renderCompletion={(onRestart) => (
            <PreviewCompletion survey={survey} onRestart={onRestart} />
          )}
        />
      </PreviewShell>
    );
  }

  return (
    <PreviewShell surveyId={surveyId}>
      <SurveyPreviewBody
        key={survey.id}
        survey={survey}
        questions={questions.questions}
        sections={sections.sections}
      />
    </PreviewShell>
  );
}


